import{_ as e,o as s,c as n,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"B 站解析与下载","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/bilibili.md","filePath":"projects/lotus-plugin/docs/bilibili.md"}'),i={name:"projects/lotus-plugin/docs/bilibili.md"};function t(p,a,r,o,c,d){return s(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="b-站解析与下载" tabindex="-1">B 站解析与下载 <a class="header-anchor" href="#b-站解析与下载" aria-label="Permalink to &quot;B 站解析与下载&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><ul><li>支持 B站长链接、短链接、BV 号、av 号和 QQ 分享卡片。</li><li>视频解析会输出图片卡片，并继续走 TuneWeave + JS 下载后发送视频文件。</li><li>直播只发送信息卡和独立播放器链接，不做直播下载。</li><li>每次下载使用独立任务目录，不复用下载文件；同一视频在多个群同时或前后脚触发时分别处理。</li><li>同一机器人发送相同文件内容时，上传按顺序执行，上一份返回后立即发送下一份；不同内容和不同机器人仍可并发。此保护覆盖 B站和抖音共用的媒体发送层，保留原标题及显示文件名，避免 QQ 内部按内容映射的缓存被并发复制覆盖。</li><li>等待发送完成后清理本任务目录，下载或发送失败也只清理本任务。</li><li>TuneWeave + JS 单 P、多 P 产物使用 BV、分 P 序号和 CID 命名，标题中的符号或超长文字不参与物理路径生成；发送时保留视频标题或分 P 标题作为显示文件名。</li><li>视频、图片和附件共用传输路径处理，特殊名称通过独立临时别名发送，避免裸 <code>%</code>、<code>%20</code>、引号等被适配器当作 URL 解码。别名在发送完成或失败后清理，原文件保留至任务清理。</li><li>ZIP 标题按 UTF-8 字节和完整字素限制长度，并处理控制字符、尾随点/空格及 Windows 保留名称。</li></ul><h2 id="指令用法" tabindex="-1">指令用法 <a class="header-anchor" href="#指令用法" aria-label="Permalink to &quot;指令用法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;B站链接或编号&gt;</span></span>
<span class="line"><span>#搜视频 &lt;关键词&gt;</span></span>
<span class="line"><span>#荷花搜视频 &lt;关键词&gt;</span></span>
<span class="line"><span>#看&lt;序号&gt;</span></span>
<span class="line"><span>#看视频 &lt;关键词&gt;</span></span>
<span class="line"><span>#荷花看视频 &lt;关键词&gt;</span></span>
<span class="line"><span>#B站下载 &lt;BV号或链接&gt;</span></span>
<span class="line"><span>#荷花下载 &lt;BV号或链接&gt;</span></span>
<span class="line"><span>#B站登录</span></span>
<span class="line"><span>#初始化环境</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="变量说明" tabindex="-1">变量说明 <a class="header-anchor" href="#变量说明" aria-label="Permalink to &quot;变量说明&quot;">​</a></h2><ul><li><code>B站链接或编号</code>：必填，支持长链、短链、BV 号、av 号和 QQ 分享卡片。</li><li><code>关键词</code>：必填，视频搜索关键词。</li><li><code>序号</code>：必填，搜索结果序号。</li><li><code>BV号或链接</code>：必填，要播放或下载的视频编号或链接。</li></ul><h2 id="补充说明" tabindex="-1">补充说明 <a class="header-anchor" href="#补充说明" aria-label="Permalink to &quot;补充说明&quot;">​</a></h2><p>解析卡片包含封面、主标题、简介、UP主、视频时长和互动数据。</p><p>B站搜索、详情及播放清单使用 TuneWeave，下载由 JS 完成，FFmpeg 合流。默认并发 4，可在锅巴或插件面板调整；分P策略继续支持 first/all/zip。每个请求使用独立目录，完成或失败后清理本任务。</p><p>登录推荐发送 <code>#B站登录</code>。二维码由 TuneWeave 创建和保存，Lotus 仅保存账号引用。Cookie、SESSDATA 的手填配置入口已移除，视频搜索与播放只使用 TuneWeave 保存的会话引用。直播间信息通过公开接口查询，不再附带旧 Cookie。旧账号文件保留；升级时配置中的旧凭据会先备份到本机 <code>data/bilibili/legacy/</code>，再清理旧字段，无法导入的会话需重新扫码。</p><p>需要 <a href="https://github.com/MOPELotus/TuneWeave/releases/tag/v1.0.0-beta.3" target="_blank" rel="noreferrer">TuneWeave 1.0.0-beta.3</a> 或更新版本，兼容搜索中的混合卡片和播放清单中的重复格式；播放地址继续支持 B站返回的 CDN 与备用地址，无需额外实验补丁。</p>`,13)])])}const h=e(i,[["render",t]]);export{u as __pageData,h as default};
